1	//! Skills guru — embedded snippet registry keyed by topic.
2	
3	use anyhow::Result;
4	
5	pub const TOPIC_ATTRACTORS: &str = "attractors";
6	pub const TOPIC_STRESSORS: &str = "stressors";
7	pub const TOPIC_PURPOSES: &str = "purposes";
8	pub const TOPIC_PERSONAS: &str = "personas";
9	pub const TOPIC_WHOLE_SYSTEM_RESIDUE: &str = "whole-system-residue";
10	pub const TOPIC_WALK_REMINDER: &str = "walk-reminder";
11	
12	const SNIPPET_ATTRACTORS: &str = include_str!("snippets/attractors.md");
13	const SNIPPET_STRESSORS: &str = include_str!("snippets/stressors.md");
14	const SNIPPET_PURPOSES: &str = include_str!("snippets/purposes.md");
15	const SNIPPET_PERSONAS: &str = include_str!("snippets/personas.md");
16	const SNIPPET_WHOLE_SYSTEM_RESIDUE: &str = include_str!("snippets/whole-system-residue.md");
17	const SNIPPET_WALK_REMINDER: &str = include_str!("snippets/walk-reminder.md");
18	
19	/// Guru block for a topic, if any.
20	pub fn block_for_topic(topic: &str) -> Option<&'static str> {
21	    match topic {
22	        TOPIC_ATTRACTORS => Some(SNIPPET_ATTRACTORS),
23	        TOPIC_STRESSORS => Some(SNIPPET_STRESSORS),
24	        TOPIC_PURPOSES => Some(SNIPPET_PURPOSES),
25	        TOPIC_PERSONAS => Some(SNIPPET_PERSONAS),
26	        TOPIC_WHOLE_SYSTEM_RESIDUE => Some(SNIPPET_WHOLE_SYSTEM_RESIDUE),
27	        TOPIC_WALK_REMINDER => Some(SNIPPET_WALK_REMINDER),
28	        _ => None,
29	    }
30	}
31	
32	/// Topics whose guru blocks attach to a skill's skill-data output.
33	pub fn topics_for_skill(skill_name: &str) -> &'static [&'static str] {
34	    match skill_name {
35	        "purpose-walk" => &[TOPIC_ATTRACTORS, TOPIC_PURPOSES],
36	        "stressor-walk" => &[
37	            TOPIC_ATTRACTORS,
38	            TOPIC_STRESSORS,
39	            TOPIC_PURPOSES,
40	            TOPIC_PERSONAS,
41	            TOPIC_WHOLE_SYSTEM_RESIDUE,
42	        ],
43	        "naive-draft" => &[TOPIC_PURPOSES],
44	        "integrate" => &[
45	            TOPIC_ATTRACTORS,
46	            TOPIC_STRESSORS,
47	            TOPIC_PURPOSES,
48	            TOPIC_WHOLE_SYSTEM_RESIDUE,
49	        ],
50	        "fmea" | "atam" => &[
51	            TOPIC_ATTRACTORS,
52	            TOPIC_STRESSORS,
53	            TOPIC_PURPOSES,
54	            TOPIC_PERSONAS,
55	            TOPIC_WHOLE_SYSTEM_RESIDUE,
56	        ],
57	        _ => &[
58	            TOPIC_ATTRACTORS,
59	            TOPIC_STRESSORS,
60	            TOPIC_PURPOSES,
61	            TOPIC_PERSONAS,
62	            TOPIC_WHOLE_SYSTEM_RESIDUE,
63	        ],
64	    }
65	}
66	
67	/// Inject guru blocks into skill-data context for the given skill.
68	pub fn inject_for_skill(skill_name: &str, context: &str) -> Result<String> {
69	    let topics = topics_for_skill(skill_name);
70	    if topics.is_empty() {
71	        return Ok(context.to_string());
72	    }
73	
74	    let mut out = context.to_string();
75	    out.push_str("\n## Guru\n\n");
76	    for (i, topic) in topics.iter().enumerate() {
77	        if let Some(block) = block_for_topic(topic) {
78	            if i > 0 {
79	                out.push('\n');
80	            }
81	            out.push_str(&format!("### {topic}\n\n"));
82	            out.push_str(block);
83	            if !block.ends_with('\n') {
84	                out.push('\n');
85	            }
86	        }
87	    }
88	    Ok(out)
89	}
90	
91	/// Token estimate for guru blocks attached to a skill.
92	pub fn token_estimate_for_skill(skill_name: &str) -> usize {
93	    topics_for_skill(skill_name)
94	        .iter()
95	        .filter_map(|topic| block_for_topic(topic))
96	        .map(|block| crate::skills::estimate_tokens(block))
97	        .sum()
98	}
