42	pub fn install(name: &str, agent: &str, global: bool) -> Result<()> {
43	    if name == "all" {
44	        return install_all(agent, global);
45	    }
46	    // Ensure the skill exists in the binary; install a thin passthrough stub (S-07).
47	    let _ = find(name).with_context(|| format!("skill '{}' not found", name))?;
48	    install_one(name, agent, global)
49	}
