51	fn install_one(name: &str, agent: &str, global: bool) -> Result<()> {
52	    let agents: Vec<&str> = if agent == "all" {
53	        vec!["claude", "cursor", "copilot", "agnostic"]
54	    } else {
55	        vec![agent]
56	    };
57	    for a in agents {
58	        let agent_parsed: install::Agent = a.parse()?;
59	        let path = install::install_path(name, &agent_parsed, global)?;
60	        let stub = install::passthrough_stub(name);
61	        install::write_skill(&path, &stub)?;
62	        println!(
63	            "Installed '{}' → {} (full content via `residual skill show {}`)",
64	            name,
65	            path.display(),
66	            name
67	        );
68	    }
69	    Ok(())
70	}
71	
72	fn install_all(agent: &str, global: bool) -> Result<()> {
73	    for (name, _, _) in SKILLS {
74	        install_one(name, agent, global)?;
75	    }
76	    Ok(())
77	}
