94	pub(crate) fn list_all_text() -> String {
95	    let mut out = String::new();
96	    out.push_str(
97	        "Skills are selectable analytical lenses (a-la-carte) — invoke only the steps your workflow needs.\n\n"
98	    );
99	    out.push_str(&format!(
100	        "{:<20} {:>7}  {:>12}  {:>10}\n",
101	        "SKILL", "VERSION", "TOKENS (~)", "GURU (~)"
102	    ));
103	    out.push_str(&format!("{}\n", "-".repeat(58)));
104	    for (name, content, version) in SKILLS {
105	        let tokens = estimate_tokens(content);
106	        let guru = guru::token_estimate_for_skill(name);
107	        if guru > 0 {
108	            out.push_str(&format!(
109	                "{:<20} {:>7}  {:>12}  +guru {:>4}\n",
110	                name, version, tokens, guru
111	            ));
112	        } else {
113	            out.push_str(&format!("{:<20} {:>7}  {:>12}  {:>10}\n", name, version, tokens, guru));
114	        }
115	    }
116	    out
117	}
