83	impl SidecarConfig {
84	    /// Load sidecar settings from a config.toml file.
85	    pub fn from_config_file(config_path: &Path) -> Result<Self> {
86	        if !config_path.is_file() {
87	            return Ok(Self::default());
88	        }
89	        let raw = std::fs::read_to_string(config_path)
90	            .with_context(|| format!("read {}", config_path.display()))?;
91	        Self::from_toml(&raw)
