95	        let parsed = parse_sidecar_section(raw)?;
96	        Ok(Self {
97	            enabled: parsed.git_sidecar_enabled,
98	            branch: parsed.git_sidecar_branch,
99	            remote: parsed.git_sidecar_remote,
100	            working_tree_policy: WorkingTreePolicy::from_str(&parsed.working_tree_policy),
101	            config_host: ConfigHost::from_str(&parsed.config_host),
102	            branch_mode: parsed.branch_mode,
103	            branch_pattern: parsed.branch_pattern,
104	        })
105	    }
106	}
