108	#[derive(Debug, Clone, PartialEq, Eq)]
109	pub struct ConfigDiscovery {
110	    pub config_path: PathBuf,
111	    pub residual_dir: PathBuf,
112	    pub source: ConfigSource,
113	}
114	
115	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
116	pub enum ConfigSource {
117	    ParentStealth,
118	    InRepo,
119	    WalkUp,
120	}
121	
122	/// Discover config following search order: parent-dir stealth → in-repo → walk up (bounded at /).
123	pub fn discover_config(start: &Path) -> Result<ConfigDiscovery> {
124	    let mut base = start.to_path_buf();
125	    if base.is_file() {
126	        base.pop();
127	    }
128	
129	    // 1. Parent-dir stealth: ../residual/config.toml relative to start directory.
130	    if let Some(parent) = base.parent() {
131	        let parent_config = parent.join("residual/config.toml");
132	        if parent_config.is_file() {
133	            return Ok(ConfigDiscovery {
134	                config_path: parent_config.clone(),
135	                residual_dir: parent.join("residual"),
136	                source: ConfigSource::ParentStealth,
137	            });
138	        }
139	    }
140	
141	    // 2. In-repo: <start>/residual/config.toml
142	    let in_repo_config = base.join("residual/config.toml");
143	    if in_repo_config.is_file() {
144	        return Ok(ConfigDiscovery {
145	            config_path: in_repo_config,
146	            residual_dir: base.join("residual"),
147	            source: ConfigSource::InRepo,
148	        });
149	    }
150	
151	    // 3. Walk up from start for residual/ directory (bounded at filesystem root).
152	    let mut dir = base;
153	    loop {
154	        let candidate = dir.join("residual");
155	        if candidate.is_dir() {
156	            return Ok(ConfigDiscovery {
157	                config_path: candidate.join("config.toml"),
158	                residual_dir: candidate,
159	                source: ConfigSource::WalkUp,
160	            });
161	        }
162	        if !dir.pop() {
163	            return Ok(ConfigDiscovery {
164	                config_path: PathBuf::from("residual/config.toml"),
165	                residual_dir: PathBuf::from("residual"),
166	                source: ConfigSource::WalkUp,
167	            });
168	        }
169	    }
170	}
