178	/// Run a git subcommand and return trimmed stdout, bailing with stderr on failure.
179	/// `index_file`, when set, scopes the call to a scratch index via `GIT_INDEX_FILE` —
180	/// this is what lets plumbing operate without ever touching the repo's real index.
181	fn git_capture(repo_root: &Path, args: &[&str], index_file: Option<&Path>) -> Result<String> {
182	    let mut cmd = git(repo_root);
183	    if let Some(idx) = index_file {
184	        cmd.env("GIT_INDEX_FILE", idx);
185	    }
186	    let out = cmd
187	        .args(args)
188	        .output()
189	        .with_context(|| format!("git {}", args.join(" ")))?;
190	    if !out.status.success() {
191	        bail!(
192	            "git {} failed: {}",
193	            args.join(" "),
194	            String::from_utf8_lossy(&out.stderr)
195	        );
196	    }
197	    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
198	}
