200	fn branch_exists(repo_root: &Path, branch: &str) -> Result<bool> {
201	    let out = git(repo_root)
202	        .args(["rev-parse", "--verify", &format!("refs/heads/{branch}")])
203	        .output()
204	        .context("git rev-parse branch")?;
205	    Ok(out.status.success())
206	}
