208	fn current_branch(repo_root: &Path) -> Result<String> {
209	    let out = git(repo_root)
210	        .args(["symbolic-ref", "--short", "HEAD"])
211	        .output()
212	        .context("git symbolic-ref")?;
213	    if out.status.success() {
214	        return Ok(String::from_utf8_lossy(&out.stdout).trim().to_string());
215	    }
216	    Ok("main".to_string())
217	}
