223	static SCRATCH_COUNTER: AtomicU64 = AtomicU64::new(0);
224	
225	/// A path under `.git/` guaranteed unique within this process, for scratch plumbing
226	/// state (index files, transient blobs) that must never collide across concurrent calls.
227	fn scratch_path(repo_root: &Path, label: &str) -> PathBuf {
228	    let n = SCRATCH_COUNTER.fetch_add(1, Ordering::Relaxed);
229	    repo_root
230	        .join(".git")
231	        .join(format!("residual-{label}-{}-{n}", std::process::id()))
232	}
