239	fn update_index_add(repo_root: &Path, index_file: &Path, sha: &str, rel_path: &str) -> Result<()> {
240	    let cacheinfo = format!("100644,{sha},{rel_path}");
241	    git_capture(
242	        repo_root,
243	        &["update-index", "--add", "--cacheinfo", &cacheinfo],
244	        Some(index_file),
245	    )?;
246	    Ok(())
247	}
