253	fn commit_tree(repo_root: &Path, tree: &str, parents: &[&str], message: &str) -> Result<String> {
254	    let mut args: Vec<&str> = vec!["commit-tree", tree];
255	    for p in parents {
256	        args.push("-p");
257	        args.push(p);
258	    }
259	    args.push("-m");
260	    args.push(message);
261	    git_capture(repo_root, &args, None)
262	}
