264	/// Compare-and-swap ref update: `old_sha` of `""` asserts the ref must not yet exist.
265	fn update_ref(repo_root: &Path, branch: &str, new_sha: &str, old_sha: &str) -> Result<()> {
266	    let refname = format!("refs/heads/{branch}");
267	    git_capture(repo_root, &["update-ref", &refname, new_sha, old_sha], None)?;
268	    Ok(())
269	}
