271	fn push_branch(repo_root: &Path, remote: &str, branch: &str) -> Result<()> {
272	    let out = git(repo_root)
273	        .args(["push", remote, branch])
274	        .output()
275	        .context("git push sidecar branch")?;
276	    if !out.status.success() {
277	        bail!(
278	            "git push {remote} {branch} failed: {}",
279	            String::from_utf8_lossy(&out.stderr)
280	        );
281	    }
282	    Ok(())
