285	/// Recursively hash-object every file under `dir` into `index_file`, rooted at
286	/// `prefix`. `exclude` is applied only at the top level of `dir` (used to keep
287	/// `config.toml` off the sidecar branch while still committing everything else).
288	fn stage_dir(
289	    repo_root: &Path,
290	    index_file: &Path,
291	    dir: &Path,
292	    prefix: &str,
293	    exclude: &[&str],
294	) -> Result<()> {
295	    for entry in std::fs::read_dir(dir).with_context(|| format!("read_dir {}", dir.display()))? {
296	        let entry = entry?;
297	        let name = entry.file_name();
298	        let name_str = name.to_string_lossy();
299	        if exclude.contains(&name_str.as_ref()) {
300	            continue;
301	        }
302	        let path = entry.path();
303	        let rel = format!("{prefix}/{name_str}");
304	        if path.is_dir() {
305	            stage_dir(repo_root, index_file, &path, &rel, &[])?;
306	        } else {
307	            let sha = hash_object(repo_root, &path)?;
308	            update_index_add(repo_root, index_file, &sha, &rel)?;
309	        }
310	    }
311	    Ok(())
312	}
