314	/// Create the sidecar branch's first commit purely via plumbing — no checkout, no
315	/// working-tree interaction, so a failure here can never leave the repo mid-switch.
316	fn bootstrap_sidecar_branch(repo_root: &Path, branch: &str) -> Result<()> {
317	    let header_path = scratch_path(repo_root, "bootstrap-csv");
318	    std::fs::write(
319	        &header_path,
320	        "id,shortname,description,naive_change,outcomes,attractor_id\n",
321	    )?;
322	    let sha = hash_object(repo_root, &header_path);
323	    let _ = std::fs::remove_file(&header_path);
324	    let sha = sha?;
325	
326	    let index_file = scratch_path(repo_root, "bootstrap-index");
327	    let tree = update_index_add(repo_root, &index_file, &sha, "residual/stressors.csv")
328	        .and_then(|()| write_tree(repo_root, &index_file));
329	    let _ = std::fs::remove_file(&index_file);
330	    let tree = tree?;
331	
332	    let commit = commit_tree(repo_root, &tree, &[], "bootstrap sidecar metadata")?;
333	    update_ref(repo_root, branch, &commit, "")
334	}
