336	/// Materialize a read-only snapshot of `branch`'s `residual/` tree into a scratch
337	/// directory under `.git/`. Read-only from git's perspective (`ls-tree`/`show`) — never
338	/// touches the working tree or index.
339	fn materialize_branch_tree(repo_root: &Path, branch: &str) -> Result<PathBuf> {
340	    if !branch_exists(repo_root, branch)? {
341	        bootstrap_sidecar_branch(repo_root, branch)?;
342	    }
343	
344	    let checkout = repo_root.join(".git").join("residual-sidecar-checkout");
345	    if checkout.exists() {
346	        std::fs::remove_dir_all(&checkout)
347	            .with_context(|| format!("clear {}", checkout.display()))?;
348	    }
349	    std::fs::create_dir_all(&checkout)?;
350	
351	    let list_out = git(repo_root)
352	        .args(["ls-tree", "-r", "--name-only", branch, "--", "residual/"])
353	        .output()
354	        .context("git ls-tree sidecar")?;
355	    if !list_out.status.success() {
356	        bail!(
357	            "git ls-tree failed: {}",
358	            String::from_utf8_lossy(&list_out.stderr)
359	        );
360	    }
361	
362	    let paths = String::from_utf8_lossy(&list_out.stdout);
363	    for rel in paths.lines().filter(|l| !l.is_empty()) {
364	        let show_out = git(repo_root)
365	            .args(["show", &format!("{branch}:{rel}")])
366	            .output()
367	            .with_context(|| format!("git show {branch}:{rel}"))?;
368	        if !show_out.status.success() {
369	            continue;
370	        }
371	        let dest = checkout.join(rel.strip_prefix("residual/").unwrap_or(rel));
372	        if let Some(parent) = dest.parent() {
373	            std::fs::create_dir_all(parent)?;
374	        }
375	        std::fs::write(&dest, &show_out.stdout)?;
376	    }
377	
378	    Ok(checkout)
379	}
380	
381	fn copy_dir_all(src: &Path, dst: &Path) -> Result<()> {
382	    std::fs::create_dir_all(dst)?;
383	    for entry in std::fs::read_dir(src)? {
384	        let entry = entry?;
385	        let path = entry.path();
386	        let dest = dst.join(entry.file_name());
387	        if path.is_dir() {
388	            copy_dir_all(&path, &dest)?;
389	        } else {
390	            std::fs::copy(&path, &dest)
391	                .with_context(|| format!("copy {} -> {}", path.display(), dest.display()))?;
392	        }
393	    }
394	    Ok(())
395	}
396	
397	fn metadata_files(root: &Path) -> Result<Vec<PathBuf>> {
398	    fn visit(root: &Path, dir: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
399	        for entry in
400	            std::fs::read_dir(dir).with_context(|| format!("read_dir {}", dir.display()))?
401	        {
402	            let entry = entry?;
403	            let path = entry.path();
404	            if path.is_dir() {
405	                visit(root, &path, files)?;
406	            } else if path.is_file() {
407	                files.push(
408	                    path.strip_prefix(root)
409	                        .with_context(|| {
410	                            format!("{} is outside {}", path.display(), root.display())
411	                        })?
412	                        .to_path_buf(),
413	                );
414	            }
415	        }
416	        Ok(())
417	    }
418	
419	    let mut files = Vec::new();
420	    visit(root, root, &mut files)?;
421	    files.sort();
422	    Ok(files)
423	}
