425	fn write_branch_edit_marker(
426	    dest_residual_dir: &Path,
427	    branch: &str,
428	    files: &[PathBuf],
429	) -> Result<()> {
430	    let mut marker = format!("branch={branch}\n");
431	    for file in files {
432	        marker.push_str(
433	            file.to_str()
434	                .with_context(|| format!("non-utf8 metadata path {}", file.display()))?,
435	        );
436	        marker.push('\n');
437	    }
438	    std::fs::write(dest_residual_dir.join(BRANCH_EDIT_MARKER), marker).with_context(|| {
439	        format!(
440	            "write branch-edit marker in {}",
441	            dest_residual_dir.display()
442	        )
443	    })
444	}
445	
446	fn validate_branch_edit_marker(dest_residual_dir: &Path, branch: &str) -> Result<()> {
447	    let marker_path = dest_residual_dir.join(BRANCH_EDIT_MARKER);
448	    let marker = std::fs::read_to_string(&marker_path).with_context(|| {
449	        format!(
450	            "residual branch save requires `residual branch edit` first; missing {}",
451	            marker_path.display()
452	        )
453	    })?;
454	    let mut lines = marker.lines();
455	    let recorded_branch = lines
456	        .next()
457	        .and_then(|line| line.strip_prefix("branch="))
458	        .context("invalid residual branch-edit marker; rerun `residual branch edit`")?;
459	    if recorded_branch != branch {
460	        bail!(
461	            "residual branch save is for '{branch}', but the materialized metadata came from '{recorded_branch}'; rerun `residual branch edit`"
462	        );
463	    }
464	
465	    let mut found_file = false;
466	    for relative in lines.filter(|line| !line.is_empty()) {
467	        let path = Path::new(relative);
468	        if path.is_absolute()
469	            || path
470	                .components()
471	                .any(|part| matches!(part, std::path::Component::ParentDir))
472	        {
473	            bail!("invalid residual branch-edit marker path '{relative}'; rerun `residual branch edit`");
474	        }
475	        found_file = true;
476	        let full_path = dest_residual_dir.join(path);
477	        if !full_path.is_file() {
478	            bail!(
479	                "residual branch save refuses incomplete metadata: '{}' is missing; rerun `residual branch edit`",
480	                full_path.display()
481	            );
482	        }
483	    }
484	    if !found_file {
485	        bail!("invalid residual branch-edit marker has no metadata files; rerun `residual branch edit`");
486	    }
487	    Ok(())
488	}
