490	/// Commit a snapshot of `source_dir` (excluding top-level `exclude` entries) as the new
491	/// tip of `branch`, via plumbing only. Returns `Ok(None)` when the snapshot is identical
492	/// to the branch tip (no-op, no empty commit). `source_dir` may safely alias a path
493	/// inside the working tree (e.g. `<repo>/residual`) — it is only ever read, never
494	/// written to or deleted, unlike the old checkout-based approach.
495	fn commit_snapshot_to_branch(
496	    repo_root: &Path,
497	    branch: &str,
498	    source_dir: &Path,
499	    exclude: &[&str],
500	    message: &str,
501	) -> Result<Option<String>> {
502	    if !branch_exists(repo_root, branch)? {
503	        bail!("sidecar branch {branch} does not exist");
504	    }
505	    let parent = rev_parse(repo_root, &format!("refs/heads/{branch}"))?;
506	    let parent_tree = rev_parse(repo_root, &format!("{parent}^{{tree}}"))?;
507	
508	    let index_file = scratch_path(repo_root, "snapshot-index");
509	    let new_tree = stage_dir(repo_root, &index_file, source_dir, "residual", exclude)
510	        .and_then(|()| write_tree(repo_root, &index_file));
511	    let _ = std::fs::remove_file(&index_file);
512	    let new_tree = new_tree?;
513	
514	    if new_tree == parent_tree {
515	        return Ok(None);
516	    }
517	
518	    let commit = commit_tree(repo_root, &new_tree, &[&parent], message)?;
519	    update_ref(repo_root, branch, &commit, &parent)?;
520	    Ok(Some(commit))
521	}
