662	/// Fork a metadata branch for `target_branch` (default: current branch) from the trunk's
663	/// tip. The only place a per-code-branch metadata branch gets created. Idempotent.
664	pub fn branch_init(
665	    repo_root: &Path,
666	    sidecar: &SidecarConfig,
667	    target_branch: Option<&str>,
668	) -> Result<String> {
669	    if !branch_exists(repo_root, &sidecar.branch)? {
670	        bootstrap_sidecar_branch(repo_root, &sidecar.branch)?;
671	    }
672	    let working = match target_branch {
673	        Some(b) => b.to_string(),
674	        None => current_branch(repo_root)?,
675	    };
676	    let resolved = resolve_branch_name(&sidecar.branch_pattern, &working);
677	    if resolved == sidecar.branch || branch_exists(repo_root, &resolved)? {
678	        return Ok(resolved);
679	    }
680	    let trunk_sha = rev_parse(repo_root, &format!("refs/heads/{}", sidecar.branch))?;
681	    update_ref(repo_root, &resolved, &trunk_sha, "")?;
682	    Ok(resolved)
683	}
