685	/// Materialize the current branch's metadata into `dest_residual_dir` for manual repair.
686	/// Strict: requires a resolved metadata branch (`residual branch init` first).
687	pub fn branch_edit(
688	    repo_root: &Path,
689	    sidecar: &SidecarConfig,
690	    dest_residual_dir: &Path,
691	) -> Result<String> {
692	    let branch = resolve_for_write(repo_root, sidecar)?;
693	    let materialized = materialize_branch_tree(repo_root, &branch)?;
694	    std::fs::create_dir_all(dest_residual_dir)?;
695	    copy_dir_all(&materialized, dest_residual_dir)?;
696	    write_branch_edit_marker(dest_residual_dir, &branch, &metadata_files(&materialized)?)?;
697	    Ok(branch)
698	}
