700	/// Save hand-edited metadata from `src_residual_dir` back to the resolved metadata branch.
701	pub fn branch_save(
702	    repo_root: &Path,
703	    sidecar: &SidecarConfig,
704	    src_residual_dir: &Path,
705	    commit_msg: &str,
706	    push: bool,
707	) -> Result<String> {
708	    let branch = resolve_for_write(repo_root, sidecar)?;
709	    validate_branch_edit_marker(src_residual_dir, &branch)?;
710	    let message = if commit_msg.is_empty() {
711	        "general - sidecar: manual branch save"
712	    } else {
713	        commit_msg
