715	    persist_metadata_to_branch(repo_root, &branch, src_residual_dir, message)?;
716	    if push {
717	        push_branch(repo_root, &sidecar.remote, &branch)?;
718	    }
719	    std::fs::remove_file(src_residual_dir.join(BRANCH_EDIT_MARKER)).with_context(|| {
720	        format!(
721	            "remove branch-edit marker from {}",
722	            src_residual_dir.display()
723	        )
724	    })?;
725	    Ok(branch)
726	}
