728	/// Merge `from`'s metadata branch into `to`'s metadata branch (both resolved from code
729	/// branch names), entirely via `git merge-tree --write-tree` — no checkout, so the
730	/// working tree is never at risk regardless of outcome. `from` must resolve to an
731	/// existing metadata branch (`residual branch init` first); `to` falls back to trunk
732	/// when unresolved, since merging back into the trunk code branch needs no dedicated
733	/// metadata branch of its own. On conflict, nothing is touched — resolve by checking
734	/// out the sidecar branch manually (e.g. in a throwaway worktree) and merging there.
735	pub fn branch_merge(
736	    repo_root: &Path,
737	    sidecar: &SidecarConfig,
738	    from_working_branch: &str,
739	    to_working_branch: &str,
740	    commit_msg: Option<&str>,
741	    push: bool,
742	) -> Result<(String, String)> {
743	    let from_branch = resolve_named_for_write(repo_root, sidecar, from_working_branch)?;
744	    let to_branch = resolve_named_for_read(repo_root, sidecar, to_working_branch)?;
745	
746	    let from_sha = rev_parse(repo_root, &format!("refs/heads/{from_branch}"))?;
747	    let to_sha = rev_parse(repo_root, &format!("refs/heads/{to_branch}"))?;
748	
749	    let merge_out = git(repo_root)
750	        .args(["merge-tree", "--write-tree", &to_sha, &from_sha])
751	        .output()
752	        .context("git merge-tree")?;
753	    let stdout = String::from_utf8_lossy(&merge_out.stdout).to_string();
754	    if !merge_out.status.success() {
755	        bail!(
756	            "merge {from_branch} into {to_branch} produced conflicts — nothing was changed; resolve manually (e.g. in a throwaway worktree on '{to_branch}') and re-run:\n{stdout}"
757	        );
758	    }
759	    let merged_tree = stdout
760	        .lines()
761	        .next()
762	        .context("empty git merge-tree output")?
763	        .trim()
764	        .to_string();
765	
766	    let message = commit_msg
767	        .map(|m| m.to_string())
768	        .unwrap_or_else(|| format!("general - sidecar: merge {from_branch} into {to_branch}"));
769	    let new_commit = commit_tree(repo_root, &merged_tree, &[&to_sha, &from_sha], &message)?;
770	    update_ref(repo_root, &to_branch, &new_commit, &to_sha)?;
771	
772	    if push {
773	        push_branch(repo_root, &sidecar.remote, &to_branch)?;
774	    }
775	    Ok((from_branch, to_branch))
776	}
