778	/// Mirror the latest commit into the current branch's resolved metadata branch, used by
779	/// the post-commit hook. Silent no-op (`Ok(None)`) whenever there's nothing to sync:
780	/// sidecar disabled, no hand-edit materialized via `branch_edit` in `config_host_dir`, or
781	/// no metadata branch resolved for the current code branch (never creates one — that's
782	/// `residual branch init`'s job alone).
783	pub fn branch_sync_commit(
784	    repo_root: &Path,
785	    sidecar: &SidecarConfig,
786	    config_host_dir: &Path,
787	) -> Result<Option<String>> {
788	    if !sidecar.enabled {
789	        return Ok(None);
790	    }
791	    if !config_host_dir.join("stressors.csv").is_file() {
792	        return Ok(None);
793	    }
794	    let branch = match resolve_for_write(repo_root, sidecar) {
795	        Ok(b) => b,
796	        Err(_) => return Ok(None),
797	    };
798	
799	    let subject = git_capture(repo_root, &["log", "-1", "--pretty=%s"], None)?;
800	    let short = git_capture(repo_root, &["rev-parse", "--short", "HEAD"], None)?;
801	    let message = format!("{subject} ({short})");
802	
803	    persist_metadata_to_branch(repo_root, &branch, config_host_dir, &message)?;
804	    Ok(Some(branch))
805	}
