813	/// Check working-tree policy for staged residual/ paths on working branch.
814	pub fn check_working_tree_policy(
815	    repo_root: &Path,
816	    sidecar: &SidecarConfig,
817	) -> Result<Option<WorkingTreeWarning>> {
818	    if !sidecar.enabled || sidecar.working_tree_policy == WorkingTreePolicy::Ignore {
819	        return Ok(None);
820	    }
821	
822	    let out = git(repo_root)
823	        .args(["diff", "--cached", "--name-only"])
824	        .output()
825	        .context("git diff --cached")?;
826	    if !out.status.success() {
827	        return Ok(None);
828	    }
829	
830	    let staged: Vec<String> = String::from_utf8_lossy(&out.stdout)
831	        .lines()
832	        .filter(|p| p.starts_with("residual/") || p.starts_with("residual\\"))
833	        .map(str::to_string)
834	        .collect();
835	
836	    if staged.is_empty() {
837	        return Ok(None);
838	    }
839	
840	    Ok(Some(WorkingTreeWarning {
841	        staged_paths: staged,
842	        policy: sidecar.working_tree_policy,
843	    }))
844	}
